#!/bin/bash
# The fake engine's script: fixed probes, printed to the transcript (stdout).
echo "probe:cinch=$(cinch version)"
echo "probe:cinch-path=$(command -v cinch)"
echo "probe:docker-path=$(command -v docker)"
echo "probe:docker-compose-path=$(command -v docker-compose)"
echo "probe:docker-ps=$(docker ps 2>&1)"
echo "probe:docker-ps-abs=$(/usr/bin/docker ps 2>&1)"
echo "probe:docker-compose-up=$(docker-compose up -d 2>&1)"
echo "probe:docker-compose-createdb=$(docker-compose exec -T postgres createdb -U deltadocs_user deltadocs_test 2>&1)"
echo "probe:docker-compose-other=$(docker-compose exec -T postgres createdb -U deltadocs_user other 2>&1)"
echo "probe:socket=$([ -S /var/run/docker.sock ] && echo present || echo absent)"
echo "probe:code-dir=$([ -e "$HOME/code" ] && echo present || echo absent)"
echo "probe:commits=$(git rev-list --count --all)"
echo "probe:branch=$(git branch --show-current)"
echo "probe:hookspath=$(git config --get core.hooksPath)"
echo "probe:go=$(go version | cut -d' ' -f3)"
echo "probe:test-db-env=$([ -n "$TEST_DATABASE_URL" ] && echo set || echo unset)"
echo "probe:env-file=$(grep -c TEST_DATABASE_URL backend/.env)"
(exec 3<>/dev/tcp/127.0.0.1/55432) 2>/dev/null && echo "probe:db-port=open" || echo "probe:db-port=closed"
echo "probe:make-dev-db=$(make dev-db 2>&1 | tail -1)"
